insert into wf_place_photo (place_id, source, image_url, width, height, license, attribution_text, attribution_url, source_ref, match_confidence, status, verified_at, storage_path, stored_at, bytes, content_type) values ('ChIJhRo4DU_GwogRUgjhMAj-pag', 'flickr', 'https://www.gowayfind.com/place-photos/batch-2026-11-15-audit/ChIJhRo4DU_GwogRUgjhMAj-pag/pl_8558661d8e7e2afc.jpg', 1280, 853, 'cc-by-2.0', 'Jared, CC BY 2.0, via Flickr', 'https://www.flickr.com/photos/93283041@N00/11840472314/', 'https://www.flickr.com/photos/93283041@N00/11840472314/', 1, 'active', now(), null, null, null, null) on conflict (place_id) do update set source=excluded.source, image_url=excluded.image_url, width=1280, height=853, license=excluded.license, attribution_text=excluded.attribution_text, attribution_url=excluded.attribution_url, source_ref=excluded.source_ref, match_confidence=1, status='active', verified_at=now(), storage_path=null, stored_at=null, bytes=null, content_type=null where wf_place_photo.image_url = 'https://upload.wikimedia.org/wikipedia/commons/8/89/Animal_Connections_Busch_Gardens_Tampa.jpg';
